// Inlines generated SQLite migrations into TypeScript modules.
//
// drizzle-kit emits a `migrations.js` that `import`s the raw .sql files, which
// would force a text-module loader into the wrangler build. Inlining keeps the
// migrations importable like any other module. Regenerated by
// `pnpm run db:generate`; do not edit the output by hand.
import { readdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";

const root = path.resolve(import.meta.dirname, "..");

const bundle = async (folder, target, exportName, label) => {
  const migrationsDir = path.join(root, "migrations", folder);
  const entries = (await readdir(migrationsDir, { withFileTypes: true }))
    .filter((entry) => entry.isDirectory())
    .map((entry) => entry.name)
    .sort();

  const parts = await Promise.all(
    entries.map(async (name) => {
      const sql = await readFile(path.join(migrationsDir, name, "migration.sql"), "utf8");
      return `  ${JSON.stringify(name)}: ${JSON.stringify(sql)},`;
    }),
  );

  await writeFile(
    path.join(root, target),
    `// GENERATED by scripts/bundle-migrations.mjs. Do not edit.\n` +
      `// Run \`pnpm run db:generate\` in packages/db to refresh.\n\n` +
      `export const ${exportName}: Record<string, string> = {\n${parts.join("\n")}\n};\n`,
  );

  console.log(`Bundled ${entries.length} ${label} migration(s) into ${target}`);
};

await bundle("do", "src/do/migrations.ts", "durableObjectMigrations", "Durable Object");
